from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
src=(r/'docs/replica/source/original.js').read_text().splitlines();defs='\n'.join(x for x in src if x.startswith(('const PAPER=','const t=','const icons=','const icon=','const btn=','const heading=','function home(')))
script=defs+"\nlet lang='ko';\n"+'''
const cases=[];for(const language of ['ko','en'])for(const width of [438,600,744,980]){lang=language;const h=document.createElement('div');h.innerHTML=home();const content=h.querySelector('.paper>div'),id=`${language}-${width}`;content.dataset.id=id;const f=document.createElement('div');f.className='fixture paper';f.style.width=width+'px';f.append(content);document.getElementById('fixtures').append(f);cases.push({id,width,english:language==='en'})}
function read(){return [...document.querySelectorAll('.fixture>div')].map(e=>{const r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},text=x=>{const c=getComputedStyle(x);return{box:box(x),text:x.textContent,color:c.color,fontSize:c.fontSize,fontWeight:c.fontWeight,lineHeight:c.lineHeight,letterSpacing:c.letterSpacing,marginTop:c.marginTop,marginBottom:c.marginBottom,maxWidth:c.maxWidth}};return{id:e.dataset.id,root:box(e),label:text(e.querySelector('.small')),title:text(e.querySelector('h2')),body:text(e.querySelector('p'))}})}function getCases(){return cases}
'''
(o/'welcomepapercontent-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
(o/'welcomepapercontent-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="welcomepapercontent-original.css"><style>.fixture{position:absolute;left:30px;top:60px;display:block;margin:0;padding:0;border:0}.fixture:not(:first-child){visibility:hidden}</style><div id="fixtures"></div><script>'+script+'</script>')
(o/'welcomepapercontent.html').write_text('''<!doctype html><meta charset="utf-8"><title>WelcomePaperContent · original isolation</title><button id="welcomepapercontent-record">Record WelcomePaperContent</button><iframe width="1400" height="650" src="welcomepapercontent-inner.html"></iframe><script>document.getElementById('welcomepapercontent-record').onclick=async()=>{const f=document.querySelector('iframe');await f.contentDocument.fonts.ready;const res=await fetch('/evidence/home-welcomepapercontent-'+(/Windows/.test(navigator.userAgent)?'windows':'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:f.contentWindow.read(),cases:f.contentWindow.getCases()})});if(!res.ok)throw Error('Record failed');document.getElementById('welcomepapercontent-record').textContent='WelcomePaperContent recorded'}</script>''')
